import { useChartTime } from '@/hooks/common/useChartTime'
import useGetHistogramData from '@/hooks/stats/useGetHistogramData'
import { SelectTab } from '@cetus/design'
import { d, symbolDataDisplayProcessing } from '@cetus/utils'
import { Box, HStack, Skeleton, Spinner, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import AllTvlChart from '../chart/AllTvlChart'

export default function TvlChartPageBlock({ statisticsData, isRefresh }: { statisticsData: any; isRefresh: boolean }) {
  const chartTypeList = [
    {
      label: 'D'
    },
    {
      label: 'W'
    },
    {
      label: 'M'
    }
  ]
  const [isLoading, setIsLoading] = useState(true)
  const [pureTvlType, setPureTvlType] = useState<'D' | 'W' | 'M'>('D')
  // 图表数据
  const { time, getHoverTime, getCurrentTime } = useChartTime()
  const { getAllTvData } = useGetHistogramData()
  const [pureTvlChartData, setPureTvlChartData] = useState<any[]>([])
  const [pureTvlCurrentData, setPureTvlCurrentData] = useState(statisticsData?.totalValueLocked)
  const [currentClmmTvl, setCurrentClmmTvl] = useState<string | undefined>()
  const [currentDlmmTvl, setCurrentDlmmTvl] = useState<string | undefined>()
  const [currentTime, setCurrentTime] = useState(time)
  const [totalClmmTvl, setTotalClmmTvl] = useState<string | undefined>()
  const [totalDlmmTvl, setTotalDlmmTvl] = useState<string | undefined>()

  const handleGetHistogramTvlData = async () => {
    setIsLoading(true)
    const tvl_res = await getAllTvData({
      limit: pureTvlType == 'D' ? 31 : pureTvlType == 'W' ? 52 : 60,
      date_type: pureTvlType == 'D' ? 'day' : pureTvlType == 'W' ? 'wek' : 'mon'
    })
    console.log('🚀 ~ file: TestData.tsx:78 ~ handleGetHistogramData ~ res:', tvl_res)
    setPureTvlChartData(tvl_res)
    const _totalClmmTvl = symbolDataDisplayProcessing(
      tvl_res?.reduce(
        (acc, current) =>
          d(acc)
            .plus(current?.clmm || 0)
            .toNumber(),
        0
      ),
      '$'
    )
    setCurrentClmmTvl(_totalClmmTvl)
    setTotalClmmTvl(_totalClmmTvl)
    const _totalDlmmTvl = symbolDataDisplayProcessing(
      tvl_res?.reduce(
        (acc, current) =>
          d(acc)
            .plus(current?.dlmm || 0)
            .toNumber(),
        0
      ),
      '$'
    )
    setCurrentDlmmTvl(_totalDlmmTvl)
    setTotalDlmmTvl(_totalDlmmTvl)
    setIsLoading(false)
  }

  const handleChangePureTvl = (data: any) => {
    console.log('🚀 ~ file: TestData.tsx:88 ~ handleChangePureTvl ~ data:', data)
    if (data) {
      getHoverTime(data.date, pureTvlType)
      setPureTvlCurrentData(
        symbolDataDisplayProcessing(
          d(data?.clmm || 0)
            .plus(data?.dlmm || 0)
            .toNumber(),
          '$'
        )
      )
      setCurrentClmmTvl(symbolDataDisplayProcessing(data?.clmm || 0, '$'))
      setCurrentDlmmTvl(symbolDataDisplayProcessing(data?.dlmm || 0, '$'))
    } else {
      getCurrentTime()
      setPureTvlCurrentData(statisticsData?.totalValueLocked)
      setCurrentClmmTvl(totalClmmTvl)
      setCurrentDlmmTvl(totalDlmmTvl)
    }
  }
  useEffect(() => {
    if (isRefresh) {
      handleGetHistogramTvlData()
    }
  }, [isRefresh])
  useEffect(() => {
    getCurrentTime()
  }, [])

  useEffect(() => {
    handleGetHistogramTvlData()
  }, [pureTvlType])

  useEffect(() => {
    if (statisticsData) {
      setPureTvlCurrentData(statisticsData?.totalValueLocked)
    }
  }, [statisticsData])

  useEffect(() => {
    if (time) {
      setCurrentTime(time)
    }
  }, [time])

  return (
    <Box w={{ base: '100%', lg: '50%' }}>
      <HStack justify="space-between">
        <VStack align="flex-start" gap="12px">
          <Text fontWeight="500">Total Value Locked</Text>
          <Skeleton isLoaded={!!pureTvlCurrentData} h="20px">
            <Text fontWeight="500" fontSize="20px" color="text_caption">
              {pureTvlCurrentData}
            </Text>
          </Skeleton>

          <Text fontWeight="500">{currentTime}</Text>
        </VStack>
        <VStack align="flex-end" gap="16px">
          <TvlLegend label="Concentrated" value={currentClmmTvl} color="text_highlight" />
          <TvlLegend label="Dynamic" value={currentDlmmTvl} color="primary_green" />
          <SelectTab
            type="outlineTab"
            tabList={chartTypeList}
            currentTab={pureTvlType}
            handleChangeTab={tab => setPureTvlType(tab.label)}
            wrapStyle={{
              w: '128px',
              h: '32px',
              p: '3px',
              borderRadius: '8px'
            }}
            itemStyle={{
              flex: '1',
              fontSize: '14px',
              margin: '0px'
            }}
          />
        </VStack>
      </HStack>
      <Box w="100%" h="260px">
        <Box w="100%" h="260px" position="relative">
          {isLoading && (
            <Box position="absolute" top="38%" left="50%" transform="translate(-50%,-50%)">
              <Spinner />
            </Box>
          )}
          <AllTvlChart data={pureTvlChartData} onChangeValue={handleChangePureTvl} />
        </Box>
      </Box>
    </Box>
  )
}

const TvlLegend = ({ label, value, color }: { label: string; value?: string; color: string }) => {
  return (
    <HStack gap="8px">
      <HStack gap="4px">
        <Skeleton w="auto" h="12px" isLoaded={value !== undefined}>
          <Text color="text_caption" fontSize="12px" whiteSpace="nowrap">
            {value}
          </Text>
        </Skeleton>

        <Text color={color} fontSize="12px">
          {label}
        </Text>
      </HStack>
      <Box w="12px" h="12px" borderRadius="4px" bg={color} />
    </HStack>
  )
}
